  ) as v(ticker, role, from_cohort, to_cohort)
  where x.cohort = v.from_cohort and x.ticker = v.ticker and x.role = v.role;
  get diagnostics k = row_count;
  if k <> 60 then raise exception 'TR2 rollback refused, nothing changed: expected to move 60 member rows back, moved %', k; end if;

  -- the 24 changed nodes: TR1's values back, only in the columns the revision changed
  update public.cohort_tree set parent_1 = 'MARKET', parent_2 = null where cohort = 'AI';
  update public.cohort_tree set parent_2 = null where cohort = 'SOFTWARE_INTERNET';
