  update public.cohort_tree set kind = 'cohort', parent_2 = null, spine = 'FMP Consumer Defensive industries minus the discount stores (which sit in RETAIL) (XLP/VDC spine)', spine_fund = 'XLP' where cohort = 'STAPLES';

  -- the 23 added nodes go only when nothing is left in them or hanging from them
  select count(*) into k from public.cohort_tree_members where cohort in ('SECTOR_XLK','SECTOR_XLC','SECTOR_XLY','SECTOR_XLP','SECTOR_XLF','SECTOR_XLV','SECTOR_XLI','SECTOR_XLE','SECTOR_XLU','SECTOR_XLB','SECTOR_XLRE','AEROSPACE_DEFENCE','PACKAGED_FOODS','BEVERAGES','HOUSEHOLD_PERSONAL','TOBACCO','FOOD_DISTRIBUTION','AGRI_PRODUCTS','STAPLES_RETAIL','FUEL_CELLS_STORAGE','IDX_FACTOR_GROWTH','IDX_FACTOR_MOMENTUM','IDX_FACTOR_LOW_VOL');
  if k <> 0 then raise exception 'TR2 rollback refused, nothing changed: % member rows still sit in a node the revision added', k; end if;
  select count(*) into k from public.cohort_tree where (parent_1 in ('SECTOR_XLK','SECTOR_XLC','SECTOR_XLY','SECTOR_XLP','SECTOR_XLF','SECTOR_XLV','SECTOR_XLI','SECTOR_XLE','SECTOR_XLU','SECTOR_XLB','SECTOR_XLRE','AEROSPACE_DEFENCE','PACKAGED_FOODS','BEVERAGES','HOUSEHOLD_PERSONAL','TOBACCO','FOOD_DISTRIBUTION','AGRI_PRODUCTS','STAPLES_RETAIL','FUEL_CELLS_STORAGE','IDX_FACTOR_GROWTH','IDX_FACTOR_MOMENTUM','IDX_FACTOR_LOW_VOL') or parent_2 in ('SECTOR_XLK','SECTOR_XLC','SECTOR_XLY','SECTOR_XLP','SECTOR_XLF','SECTOR_XLV','SECTOR_XLI','SECTOR_XLE','SECTOR_XLU','SECTOR_XLB','SECTOR_XLRE','AEROSPACE_DEFENCE','PACKAGED_FOODS','BEVERAGES','HOUSEHOLD_PERSONAL','TOBACCO','FOOD_DISTRIBUTION','AGRI_PRODUCTS','STAPLES_RETAIL','FUEL_CELLS_STORAGE','IDX_FACTOR_GROWTH','IDX_FACTOR_MOMENTUM','IDX_FACTOR_LOW_VOL')) and cohort not in ('SECTOR_XLK','SECTOR_XLC','SECTOR_XLY','SECTOR_XLP','SECTOR_XLF','SECTOR_XLV','SECTOR_XLI','SECTOR_XLE','SECTOR_XLU','SECTOR_XLB','SECTOR_XLRE','AEROSPACE_DEFENCE','PACKAGED_FOODS','BEVERAGES','HOUSEHOLD_PERSONAL','TOBACCO','FOOD_DISTRIBUTION','AGRI_PRODUCTS','STAPLES_RETAIL','FUEL_CELLS_STORAGE','IDX_FACTOR_GROWTH','IDX_FACTOR_MOMENTUM','IDX_FACTOR_LOW_VOL');
  if k <> 0 then raise exception 'TR2 rollback refused, nothing changed: % nodes still hang from a node the revision added', k; end if;
  delete from public.cohort_tree where cohort in ('SECTOR_XLK','SECTOR_XLC','SECTOR_XLY','SECTOR_XLP','SECTOR_XLF','SECTOR_XLV','SECTOR_XLI','SECTOR_XLE','SECTOR_XLU','SECTOR_XLB','SECTOR_XLRE','AEROSPACE_DEFENCE','PACKAGED_FOODS','BEVERAGES','HOUSEHOLD_PERSONAL','TOBACCO','FOOD_DISTRIBUTION','AGRI_PRODUCTS','STAPLES_RETAIL','FUEL_CELLS_STORAGE','IDX_FACTOR_GROWTH','IDX_FACTOR_MOMENTUM','IDX_FACTOR_LOW_VOL');
  get diagnostics k = row_count;
  if k <> 23 then raise exception 'TR2 rollback refused, nothing changed: expected to remove 23 added nodes, removed %', k; end if;

  -- PROOF
  set constraints all immediate;   -- the parent and member keys are checked here, not at commit
  select count(*) into n from public.cohort_tree;
  select count(*) into m from public.cohort_tree_members;
  if n <> 91 or m <> 771 then raise exception 'TR2 rollback proof: expected 91 nodes and 771 member rows, found % and %', n, m; end if;
  if not exists (select 1 from public.cohort_tree where cohort = 'FRONTIER') then raise exception 'TR2 rollback proof: FRONTIER is not back'; end if;
  select count(*) into k from public.cohort_tree where parent_1 is null;
  if k <> 1 then raise exception 'TR2 rollback proof: expected one root, found %', k; end if;
  select string_agg(format('%s.%s is %s (TR1 loaded %s)', b.cohort, b.col, coalesce(quote_literal(to_jsonb(t) ->> b.col), 'null'), coalesce(quote_literal(b.val), 'null')), '; ') into drift
